import{_ as e,C as r,c as i,o as t,j as n,G as l,b as a,a0 as s,a as d,w as o,a1 as g}from"./chunks/framework.DKRgXLPU.js";const k=JSON.parse('{"title":"Ernæring til præcisionspræstation","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/nutrition/index.md","filePath":"da/education/nutrition/index.md"}');const u=e({name:"da/education/nutrition/index.md"},[["render",function(e,k,u,p,m,h){const f=r("AdBanner"),b=r("Mermaid"),v=r("AdInArticle");return t(),i("div",null,[k[2]||(k[2]=n("h1",{id:"ernæring-til-præcisionspræstation",tabindex:"-1"},[d("Ernæring til præcisionspræstation "),n("a",{class:"header-anchor",href:"#ernæring-til-præcisionspræstation","aria-label":'Permalink to "Ernæring til præcisionspræstation"'},"​")],-1)),l(f),k[3]||(k[3]=n("p",null,[d("Petanque er en præcisionssport, ikke en udholdenhedssport. Dine ernæringsmæssige behov er anderledes end en maratonløbers eller en fodboldspillers. Det vigtigste er "),n("strong",null,"hjernens brændstofstabilitet"),d(" - at holde dit sind skarpt og dine hænder stabile gennem en lang konkurrencedag.")],-1)),k[4]||(k[4]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Den store idé"),n("p",null,[n("strong",null,"Din hjerne er dit vigtigste redskab i petanque. Giv den stabil brændstof, ikke rutsjebaneenergi."),d(" Fokuser på protein, sunde fedtstoffer og at holde dig hydreret. Undgå sukkerstigninger.")])],-1)),(t(),a(g,null,{default:o(()=>[l(b,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BSukker%2FSimple%20kulhydrater%5D%20--%3E%20B%5BBlodsukkerstigning%5D%0A%20%20%20%20B%20--%3E%20C%5BInsulinfrigivelse%5D%0A%20%20%20%20C%20--%3E%20D%5BBlodsukkernedbrud%5D%0A%20%20%20%20D%20--%3E%20E%5BAdrenalinrespons%5D%0A%20%20%20%20E%20--%3E%20F%5BRystelser%20og%20angst%5D%0A%0A%20%20%20%20G%5BProtein%20og%20sunde%20fedtstoffer%5D%20--%3E%20H%5BStabilt%20blodsukker%5D%0A%20%20%20%20H%20--%3E%20I%5BKonsekvent%20energi%5D%0A%20%20%20%20I%20--%3E%20J%5BSkarpt%20fokus%5D%0A%20%20%20%20J%20--%3E%20K%5BRolige%20h%C3%A6nder%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:o(()=>[...k[0]||(k[0]=[d(" Loading... ",-1)])]),_:1})),k[5]||(k[5]=s('<h2 id="præcisionsatletens-udfordring" tabindex="-1">Præcisionsatletens udfordring <a class="header-anchor" href="#præcisionsatletens-udfordring" aria-label="Permalink to &quot;Præcisionsatletens udfordring&quot;">​</a></h2><p>I modsætning til højintensive sportsgrene kræver petanque ikke massive glykogenlagre eller hurtig energiopfyldning. Det, det kræver, er:</p><ul><li><strong>Stabilt blodsukker</strong> - ingen stigninger eller fald</li><li><strong>Konsekvent mental klarhed</strong> - fokus der varer hele dagen</li><li><strong>Stille hænder</strong> - ingen rystelser eller rystelser</li><li><strong>Rolige nerver</strong> - lav angst og stressrespons</li></ul><p>Din ernæringsstrategi bør optimere efter disse faktorer, ikke efter rå energiproduktion.</p><h2 id="problemet-med-sukker-og-simple-kulhydrater" tabindex="-1">Problemet med sukker og simple kulhydrater <a class="header-anchor" href="#problemet-med-sukker-og-simple-kulhydrater" aria-label="Permalink to &quot;Problemet med sukker og simple kulhydrater&quot;">​</a></h2><p>Mange atleter vælger som standard en kulhydratrig kost. For petanque-spillere kan dette faktisk skade præstationen.</p><h3 id="blodsukker-rutsjebanen" tabindex="-1">Blodsukker-rutsjebanen <a class="header-anchor" href="#blodsukker-rutsjebanen" aria-label="Permalink to &quot;Blodsukker-rutsjebanen&quot;">​</a></h3><p>Når du spiser sukker eller simple kulhydrater:</p><ol><li>Blodsukkeret stiger hurtigt</li><li>Insulin frigives for at sænke det</li><li>Blodsukkerfald (hypoglykæmi)</li><li>Din krop frigiver adrenalin for at kompensere</li><li>Du oplever rystelser, angst og dårlig fokus</li></ol><p><strong>Dette er det modsatte af, hvad du har brug for til præcision.</strong></p><h3 id="symptomer-pa-ustabilitet-i-blodsukkeret" tabindex="-1">Symptomer på ustabilitet i blodsukkeret <a class="header-anchor" href="#symptomer-pa-ustabilitet-i-blodsukkeret" aria-label="Permalink to &quot;Symptomer på ustabilitet i blodsukkeret&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Indvirkning på ydeevne</th></tr></thead><tbody><tr><td>Rystende hænder</td><td>Inkonsekvent udgivelse</td></tr><tr><td>Koncentrationsbesvær</td><td>Dårlig beslutningstagning</td></tr><tr><td>Irritabilitet</td><td>Teamkonflikt, dårlig ro</td></tr><tr><td>Træthed efter måltider</td><td>Eftermiddagsnedtur</td></tr><tr><td>Angst</td><td>Trykfølsomhed</td></tr><tr><td>Hjernetåge</td><td>Langsom taktisk tænkning</td></tr></tbody></table><h2 id="en-bedre-tilgang-stabil-energi" tabindex="-1">En bedre tilgang: Stabil energi <a class="header-anchor" href="#en-bedre-tilgang-stabil-energi" aria-label="Permalink to &quot;En bedre tilgang: Stabil energi&quot;">​</a></h2><p>Målet er at forsyne din hjerne med regelmæssigt brændstof uden rutsjebanen.</p><h3 id="nøgleprincipper" tabindex="-1">Nøgleprincipper <a class="header-anchor" href="#nøgleprincipper" aria-label="Permalink to &quot;Nøgleprincipper&quot;">​</a></h3><ol><li><strong>Prioriter protein og sunde fedtstoffer</strong> - De giver langsom, stabil energi</li><li><strong>Vælg komplekse kulhydrater frem for simple</strong> - Hvis du spiser kulhydrater, så vælg dem, der fordøjes langsomt</li><li><strong>Undgå sukkerstigninger</strong> - Især før og under konkurrence</li><li><strong>Hold jer hydreret</strong> - Dehydrering påvirker koncentrationen betydeligt</li><li><strong>Spis regelmæssigt</strong> - Lad dig ikke blive for sulten</li></ol><h3 id="madvarer-der-hjælper" tabindex="-1">Madvarer der hjælper <a class="header-anchor" href="#madvarer-der-hjælper" aria-label="Permalink to &quot;Madvarer der hjælper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Madtype</th><th>Eksempler</th><th>Hvorfor det virker</th></tr></thead><tbody><tr><td>Protein</td><td>Æg, nødder, ost, kød</td><td>Langsom fordøjelse, stabil energi</td></tr><tr><td>Sunde fedtstoffer</td><td>Avocado, olivenolie, nødder</td><td>Langtidsholdbart brændstof</td></tr><tr><td>Komplekse kulhydrater</td><td>Grøntsager, bælgfrugter</td><td>Fiber forsinker absorptionen</td></tr><tr><td>Frugt med lavt sukkerindhold</td><td>Bær, æbler</td><td>Næringsstoffer uden pigge</td></tr></tbody></table><h3 id="madvarer-der-skal-begrænses" tabindex="-1">Madvarer, der skal begrænses <a class="header-anchor" href="#madvarer-der-skal-begrænses" aria-label="Permalink to &quot;Madvarer, der skal begrænses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Madtype</th><th>Eksempler</th><th>Hvorfor det er problematisk</th></tr></thead><tbody><tr><td>Sukker</td><td>Slik, sodavand, kager</td><td>Hurtig stigning og styrt</td></tr><tr><td>Hvidt brød/pasta</td><td>Sandwiches, pastaretter</td><td>Hurtig omdannelse til sukker</td></tr><tr><td>Frugtjuice</td><td>Appelsinjuice, smoothies</td><td>Koncentreret sukker</td></tr><tr><td>Energidrikke</td><td>De fleste kommercielle mærker</td><td>Sukker + koffein crash</td></tr></tbody></table><h2 id="ernæring-pa-konkurrencedagen" tabindex="-1">Ernæring på konkurrencedagen <a class="header-anchor" href="#ernæring-pa-konkurrencedagen" aria-label="Permalink to &quot;Ernæring på konkurrencedagen&quot;">​</a></h2><h3 id="før-konkurrencen" tabindex="-1">Før konkurrencen <a class="header-anchor" href="#før-konkurrencen" aria-label="Permalink to &quot;Før konkurrencen&quot;">​</a></h3><p><strong>2-3 timer før:</strong></p><ul><li>Balanceret måltid med protein, fedt og grøntsager</li><li>Undgå tunge kulhydrater, der kan forårsage døsighed</li><li>Eksempel: Æg med grøntsager eller salat med kylling</li></ul><p><strong>1 time før:</strong></p><ul><li>Let snack om nødvendigt</li><li>Nødder, ost eller en lille portion protein</li><li>Undgå alt sukkerholdigt</li></ul><h3 id="under-konkurrencen" tabindex="-1">Under konkurrencen <a class="header-anchor" href="#under-konkurrencen" aria-label="Permalink to &quot;Under konkurrencen&quot;">​</a></h3><p><strong>Mellem kampene:</strong></p><ul><li>Vand (vigtigst)</li><li>Små proteinsnacks (nødder, ost, kød)</li><li>Undgå sukkerholdige snacks og drikkevarer</li></ul><p><strong>Tegn på, at du skal spise:</strong></p><ul><li>Koncentrationsbesvær</li><li>Irritabilitet</li><li>Følelse af rystelse</li><li>Hovedpine</li></ul><h3 id="efter-konkurrencen" tabindex="-1">Efter konkurrencen <a class="header-anchor" href="#efter-konkurrencen" aria-label="Permalink to &quot;Efter konkurrencen&quot;">​</a></h3><ul><li>Genopfyld med et afbalanceret måltid</li><li>Rehydrer fuldt ud</li><li>&quot;Beløn&quot; ikke dig selv med sukker - det vil påvirke din restitution</li></ul><h2 id="hydrering" tabindex="-1">Hydrering <a class="header-anchor" href="#hydrering" aria-label="Permalink to &quot;Hydrering&quot;">​</a></h2><p>Dehydrering påvirker den kognitive funktion, før du føler dig tørstig.</p><h3 id="retningslinier" tabindex="-1">Retningslinier <a class="header-anchor" href="#retningslinier" aria-label="Permalink to &quot;Retningslinier&quot;">​</a></h3><ul><li><strong>Start med at drikke væske</strong> - Drik vand i løbet af dagen før konkurrencen</li><li><strong>Under leg</strong> - Drik regelmæssigt vand, vent ikke til du er tørstig</li><li><strong>Undgå for meget koffein</strong> - Det er et vanddrivende middel</li><li><strong>Vær opmærksom på tegn</strong> - Hovedpine, mørk urin, træthed</li></ul><h3 id="hvor-meget" tabindex="-1">Hvor meget? <a class="header-anchor" href="#hvor-meget" aria-label="Permalink to &quot;Hvor meget?&quot;">​</a></h3><p>En generel retningslinje: Sigt efter en lysegul urin. Hvis den er mørk, har du brug for mere vand.</p><h2 id="lavkulhydratmuligheden" tabindex="-1">Lavkulhydratmuligheden <a class="header-anchor" href="#lavkulhydratmuligheden" aria-label="Permalink to &quot;Lavkulhydratmuligheden&quot;">​</a></h2><p>Nogle præcisionsatleter følger lavkulhydrat- eller ketogene diæter. Teorien:</p><p><strong>Potentielle fordele:</strong></p><ul><li>Meget stabilt blodsukker (ingen mulige stigninger)</li><li>Konsekvent mental klarhed</li><li>Reduceret angst og rystelser</li><li>Ingen energinedbrud eftermiddagen</li></ul><p><strong>Overvejelser:</strong></p><ul><li>Kræver tilvænningsperiode (1-2 uger)</li><li>Ikke egnet til alle</li><li>Kræver planlægning og engagement</li><li>Kontakt først en sundhedsudbyder</li></ul>',45)),l(v),k[6]||(k[6]=s('<p>Dette er en avanceret strategi - ikke nødvendig for alle, men værd at overveje, hvis blodsukkerstabilitet er et væsentligt problem for dig.</p><h2 id="mad-som-øvelse-træning-af-din-krop" tabindex="-1">Mad som øvelse: Træning af din krop <a class="header-anchor" href="#mad-som-øvelse-træning-af-din-krop" aria-label="Permalink to &quot;Mad som øvelse: Træning af din krop&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Kritisk koncept</p><p><strong>Mad er ikke bare brændstof - det er noget, du træner med.</strong> Ligesom du træner dit kast, skal du øve din ernæring for at gøre din krop fortrolig med at spise på konkurrencedagen.</p></div><h3 id="hvorfor-er-fødevarepraksis-vigtig" tabindex="-1">Hvorfor er fødevarepraksis vigtig <a class="header-anchor" href="#hvorfor-er-fødevarepraksis-vigtig" aria-label="Permalink to &quot;Hvorfor er fødevarepraksis vigtig&quot;">​</a></h3><p>Dit fordøjelsessystem kan trænes. Det, du spiser regelmæssigt, bliver det, din krop forventer og håndterer bedst. Hvis du kun spiser protein og grøntsager på konkurrencedage, vil din krop ikke være tilpasset det.</p><p><strong>Problemet:</strong></p><ul><li>At spise ukendt mad på konkurrencedagen kan forårsage fordøjelsesbesvær</li><li>Din krop har brug for tid til at tilpasse sig nye spisemønstre</li><li>Stress + ukendt mad = potentielle maveproblemer</li><li>Præstationsangst er slemt nok uden at det øger fordøjelsesangsten</li></ul><p><strong>Løsningen:</strong></p><ul><li>Øv din konkurrenceernæring under træning</li><li>Gør din konkurrencedagsmad til en del af din regelmæssige rutine</li><li>Træn din krop til at være komfortabel med mad med stabil energi</li></ul><h3 id="tilpasningsprocessen" tabindex="-1">Tilpasningsprocessen <a class="header-anchor" href="#tilpasningsprocessen" aria-label="Permalink to &quot;Tilpasningsprocessen&quot;">​</a></h3>',10)),(t(),a(g,null,{default:o(()=>[l(b,{id:"mermaid-590",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BNuv%C3%A6rende%20kost%5D%20--%3E%20B%5BGradvise%20%C3%A6ndringer%5D%0A%20%20%20%20B%20--%3E%20C%5BKropstilpasning%20%3Cbr%2F%3E%202-4%20uger%5D%0A%20%20%20%20C%20--%3E%20D%5BNy%20normal%5D%0A%20%20%20%20D%20--%3E%20E%5BKonkurrenceklar%5D%0A%0A%20%20%20%20F%5BPludselig%20%C3%A6ndring%20%3Cbr%2F%3E%20Konkurrencedag%5D%20--%3E%20G%5BFord%C3%B8jelsesbesv%C3%A6r%5D%0A%20%20%20%20G%20--%3E%20H%5BD%C3%A5rlig%20pr%C3%A6station%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:o(()=>[...k[1]||(k[1]=[d(" Loading... ",-1)])]),_:1})),k[7]||(k[7]=s('<p>Når du ændrer din kost:</p><ol><li><strong>Uge 1-2:</strong> Din krop vænner sig til nye fødevarer, men den kan føles anderledes</li><li><strong>Uge 3-4:</strong> Tilpasning sker, nye fødevarer føles normale</li><li><strong>Uge 5+:</strong> Din krop er komfortabel og effektiv med disse fødevarer</li></ol><p><strong>Derfor kan du ikke bare &quot;spise sundt&quot; på konkurrencedagen og forvente optimale resultater.</strong></p><h3 id="sadan-øver-du-dig-i-din-ernæring" tabindex="-1">Sådan øver du dig i din ernæring <a class="header-anchor" href="#sadan-øver-du-dig-i-din-ernæring" aria-label="Permalink to &quot;Sådan øver du dig i din ernæring&quot;">​</a></h3><h4 id="_1-start-under-træning" tabindex="-1">1. Start under træning <a class="header-anchor" href="#_1-start-under-træning" aria-label="Permalink to &quot;1. Start under træning&quot;">​</a></h4><p><strong>Øv din konkurrencedagsspisning under træningssessionerne:</strong></p><ul><li>Spis det samme måltid før træning, som du ville spise før konkurrence</li><li>Medbring de samme snacks, som du ville medbringe til en turnering</li><li>Læg mærke til, hvordan din krop reagerer</li><li>Justér baseret på, hvad der virker</li></ul><p><strong>Eksempel på træningsdag:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-gør-det-til-din-normale" tabindex="-1">2. Gør det til din normale <a class="header-anchor" href="#_2-gør-det-til-din-normale" aria-label="Permalink to &quot;2. Gør det til din normale&quot;">​</a></h4><p><strong>Hvis du ikke har en &quot;konkurrencediæt&quot; og en &quot;almindelig diæt&quot;</strong> - dette skaber to problemer:</p><ul><li>Din krop tilpasser sig aldrig helt til nogen af delene</li><li>Konkurrencemad føles uvant og stressende</li></ul><p><strong>I stedet:</strong></p><ul><li>Gør mad med stabil energi til din daglige norm</li><li>Din krop bliver effektiv til at bruge protein og fedt</li><li>Konkurrencedagen føles normal, ikke anderledes</li><li>Ingen fordøjelsesoverraskelser</li></ul><h4 id="_3-test-og-forfin" tabindex="-1">3. Test og forfin <a class="header-anchor" href="#_3-test-og-forfin" aria-label="Permalink to &quot;3. Test og forfin&quot;">​</a></h4><p><strong>Brug træning til at eksperimentere:</strong></p><table tabindex="0"><thead><tr><th>Prøve</th><th>Hvad man skal bemærke</th><th>Tilpasse</th></tr></thead><tbody><tr><td>Måltider før træning</td><td>Energiniveauer, fokus</td><td>Find dit optimale vindue</td></tr><tr><td>Forskellige proteinkilder</td><td>Fordøjelse, komfort</td><td>Identificer, hvad der fungerer bedst</td></tr><tr><td>Snacktyper</td><td>Vedvarende energi</td><td>Find dine yndlingssnacks</td></tr><tr><td>Hydreringsmængder</td><td>Koncentration, toiletpauser</td><td>Balanceindtag</td></tr></tbody></table><p><strong>Før en simpel logbog:</strong></p><ul><li>Hvad du spiste og hvornår</li><li>Hvordan du havde det under træningen</li><li>Energiniveauer og fokus</li><li>Eventuelle fordøjelsesproblemer</li></ul><h4 id="_4-skab-komfort-og-selvtillid" tabindex="-1">4. Skab komfort og selvtillid <a class="header-anchor" href="#_4-skab-komfort-og-selvtillid" aria-label="Permalink to &quot;4. Skab komfort og selvtillid&quot;">​</a></h4><p><strong>Den psykologiske fordel:</strong></p><p>Når du har øvet din ernæring hundredvis af gange under træning:</p><ul><li>Du ved præcis, hvordan din krop vil reagere</li><li>Ingen bekymring over madvalg</li><li>Én ting mindre at bekymre sig om på konkurrencedagen</li><li>Tillid til din forberedelse</li></ul><p><strong>Dette er det samme princip som at øve dit kast</strong> - gentagelse opbygger komfort og pålidelighed.</p><h3 id="almindelige-tilpasningsudfordringer" tabindex="-1">Almindelige tilpasningsudfordringer <a class="header-anchor" href="#almindelige-tilpasningsudfordringer" aria-label="Permalink to &quot;Almindelige tilpasningsudfordringer&quot;">​</a></h3><details class="details custom-block"><summary>Overgang fra kulhydratrig til energirig kost</summary><p><strong>Udfordring:</strong> Du er vant til brød, pasta og sukkerholdige snacks</p><p><strong>Tilvænningsperiode:</strong> 2-4 uger</p><p><strong>Hvad du kan forvente:</strong></p><ul><li>Uge 1: Kan føles anderledes, trang til gammeldags mad</li><li>Uge 2: Energien stabiliserer sig, trangen mindskes</li><li>Uge 3-4: Ny normal, kropseffektiv med fedt/protein</li></ul><p><strong>Sådan øver du dig:</strong></p><ul><li>Start med ét måltid ad gangen</li><li>Erstat først simple kulhydrater med komplekse kulhydrater</li><li>Øg gradvist protein og sunde fedtstoffer</li><li>Øv dig først under træning med lav indsats</li></ul></details><details class="details custom-block"><summary>At finde fødevarer, der virker for dig</summary><p><strong>Udfordring:</strong> Ikke alle fordøjer den samme mad godt</p><p><strong>Hvad skal testes:</strong></p><ul><li>Forskellige proteinkilder (æg vs. kød vs. nødder)</li><li>Måltidernes tidspunkt (2 timer vs. 3 timer før)</li><li>Portionsstørrelser (for meget = sløv, for lidt = sulten)</li><li>Specifikke fødevarer, der forårsager ubehag</li></ul><p><strong>Øvelsesmetode:</strong></p><ul><li>Prøv én variabel ad gangen</li><li>Giv hver test 2-3 træningssessioner</li><li>Læg mærke til, hvad der får dig til at føle dig bedst tilpas</li><li>Byg din personlige &quot;konkurrencemenu&quot;</li></ul></details><details class="details custom-block"><summary>Håndtering af turneringsmadmiljøer</summary><p><strong>Udfordring:</strong> Turneringer har ofte begrænsede madmuligheder</p><p><strong>Øvelsesløsning:</strong></p><ul><li>Medbring altid dine egne snacks (øv dig i dette)</li><li>Undersøg steder på forhånd, når det er muligt</li><li>Hav backupmuligheder, som du ved virker</li><li>Øv dig i at spise i forskellige miljøer</li></ul><p><strong>Mental forberedelse:</strong></p><ul><li>Stol ikke på maden på stedet</li><li>Behandl mad som en del af dit udstyr</li><li>Pak det, som du pakker dine boules</li></ul></details><h3 id="_30-dages-ernæringspraksisplan" tabindex="-1">30-dages ernæringspraksisplan <a class="header-anchor" href="#_30-dages-ernæringspraksisplan" aria-label="Permalink to &quot;30-dages ernæringspraksisplan&quot;">​</a></h3><p><strong>Mål:</strong> Gør stabil energispisning til din behagelige normalitet</p><p><strong>Uge 1-2: Fundament</strong></p><ul><li>Erstat ét måltid om dagen med konkurrencemad</li><li>Øv dig i ernæring før træning</li><li>Begynd at medbringe snacks til træning</li><li>Læg mærke til, hvordan din krop reagerer</li></ul><p><strong>Uge 3-4: Udvidelse</strong></p><ul><li>Lav to måltider om dagen stabilt energifokuserede</li><li>Øv dig i at spise hele konkurrencedagen på træningsdagene</li><li>Forfin dine snackvalg</li><li>Lav din liste over madvarer</li></ul><p><strong>Uge 5+: Mestring</strong></p><ul><li>Stabil energikost er din nye normal</li><li>Kroppen er fuldt tilpasset</li><li>Konkurrencedagen føles rutinemæssig</li><li>Tillid til din ernæring</li></ul><h3 id="dit-konkurrencemadsæt" tabindex="-1">Dit konkurrencemadsæt <a class="header-anchor" href="#dit-konkurrencemadsæt" aria-label="Permalink to &quot;Dit konkurrencemadsæt&quot;">​</a></h3><p><strong>Øv dig i at pakke dette til hver træningssession:</strong></p><p><strong>Før konkurrencen (2-3 timer før):</strong></p><ul><li>[ ] Proteinkilde (æg, kød eller nødder)</li><li>[ ] Grøntsager eller salat</li><li>[ ] Sundt fedt (avocado, olivenolie, ost)</li></ul><p><strong>Under konkurrencen:</strong></p><ul><li>[ ] Vandflaske (genopfyldelig)</li><li>[ ] Blandede nødder (små portioner)</li><li>[ ] Hårdkogte æg (hvis du kan holde dem kolde)</li><li>[ ] Osteterninger eller strengeost</li><li>[ ] Tørret eller tørret kød</li><li>[ ] Backup-snacks</li></ul><p><strong>Jo mere du øver dig med dette sæt, jo mere automatisk bliver det.</strong></p><h2 id="praktiske-tips" tabindex="-1">Praktiske tips <a class="header-anchor" href="#praktiske-tips" aria-label="Permalink to &quot;Praktiske tips&quot;">​</a></h2><h3 id="nemme-konkurrencesnacks" tabindex="-1">Nemme konkurrencesnacks <a class="header-anchor" href="#nemme-konkurrencesnacks" aria-label="Permalink to &quot;Nemme konkurrencesnacks&quot;">​</a></h3><ul><li>Blandede nødder (usaltede)</li><li>Hårdkogte æg</li><li>Osteterninger</li><li>Tørret oksekød eller kalkun</li><li>Grøntsager med hummus</li><li>Oliven</li></ul><h3 id="hvad-skal-man-undga" tabindex="-1">Hvad skal man undgå <a class="header-anchor" href="#hvad-skal-man-undga" aria-label="Permalink to &quot;Hvad skal man undgå&quot;">​</a></h3><ul><li>Snacks til automater</li><li>Sukkerholdige sportsdrikke</li><li>Bagværk og kager</li><li>Slik- og chokoladebarer</li><li>De fleste &quot;energi&quot;-barer (tjek sukkerindholdet)</li></ul><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>Din hjerne er dit vigtigste redskab i petanque. Giv den stabil brændstof, ikke rutsjebaneenergi. Og øv dig i din ernæring, ligesom du øver dit kast - gentagelse skaber komfort og pålidelighed.</p></blockquote><p>Fokuser på protein, sunde fedtstoffer og at holde dig hydreret. Undgå sukkerstigninger. <strong>Vigtigst af alt: Gør din konkurrencedags ernæring til din daglige ernæring.</strong> Din krop har brug for træning for at præstere bedst muligt.</p><p><strong>Husk:</strong> Du ville ikke møde op til en turnering med en kasteteknik, du aldrig har øvet dig på. Mød heller ikke op med en ernæringsstrategi, du aldrig har øvet dig på.</p>',52)),l(f)])}]]);export{k as __pageData,u as default};
